48		public static void migrateDeskIntegration()
49		{
50			try
51			{
52				LOGGER.info("Desk Migration Started for "+ SASThreadLocal.getLoginName());
53				Map<Long, String> modules = new HashMap<Long, String>();
54				setModules(modules);
55				if(CommonUtil.isEmpty(modules) || modules.isEmpty())
56				{
57					LOGGER.info("Application log type is empty");
58					return;
59				}
60				List<Long> ProjectIDs = ProjectHandler.getProjectIDs(true);
61				
62				if(CommonUtil.isEmpty(ProjectIDs) || ProjectIDs.isEmpty())
63				{
64					LOGGER.info("There are no projects.");
65					return;
66				}
67				
68				for (int i = 0; i < ProjectIDs.size(); i++)
69				{
70					Long projectID = ProjectIDs.get(i);
71					addDeskConfiguration(modules, projectID);
72				}
73			}
74			catch(Exception e)
75			{
76				LOGGER.log(Level.SEVERE, "Exception in desk migration.", e);
77			}
78		}
