80		private static void addDeskConfiguration(Map<Long, String> modules, long projectID)
81		{
82			JSONObject configuration = new JSONObject();
83			
84			try
85			{
86				SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.DESKINTEGRATION));
87				sq.addSelectColumn(Column.getColumn(AppticsConstants.DESKINTEGRATION, "*"));
88				sq.addSelectColumn(Column.getColumn(AppticsConstants.MODULEINTEGRATION, "*"));
89				
90				Criteria JOIN = new Criteria(Column.getColumn(AppticsConstants.DESKINTEGRATION, AppticsConstants.APPID), Column.getColumn(AppticsConstants.MODULEINTEGRATION, AppticsConstants.APPID), QueryConstants.EQUAL);
91				JOIN = JOIN.and(new Criteria(Column.getColumn(AppticsConstants.MODULEINTEGRATION, "IntegrationType" ), "Desk", QueryConstants.EQUAL, false));
92				sq.addJoin(new Join(AppticsConstants.DESKINTEGRATION, AppticsConstants.MODULEINTEGRATION, JOIN, Join.LEFT_JOIN));
93				
94				Criteria c = new Criteria(Column.getColumn(AppticsConstants.DESKINTEGRATION, AppticsConstants.APPID), projectID, QueryConstants.EQUAL); 
95				sq.setCriteria(c);
96				DataObject dobj = DBHandler.getPersistence().get(sq);
97				
98				LOGGER.log(Level.INFO, dobj.toString());
99				if (!dobj.containsTable(AppticsConstants.DESKINTEGRATION))
100				{
101					LOGGER.info("No rows found for the project " + projectID);
102					return;
103				}
104				
105				@SuppressWarnings("unchecked")
106				Iterator<Row> deskRows = dobj.getRows(AppticsConstants.DESKINTEGRATION);
107				while (deskRows.hasNext())
108				{
109					Row deskRow = deskRows.next();
110					Long orgID = (Long) deskRow.get(AppticsConstants.ORGID);
111					String departmentID = (String) deskRow.get(AppticsConstants.DEPARTMENTID);
112					
113					if(CommonUtil.isEmpty(orgID) || CommonUtil.isEmpty(departmentID))
114					{
115						LOGGER.log(Level.INFO, "OrgID and DepartmentID in Empty");
116						continue;
117					}
118					
119					String orgName = (String) deskRow.get(AppticsConstants.ORGNAME);
120					String departmentname = (String) deskRow.get(AppticsConstants.DEPARTMENTNAME);
121					String guestContactID = (String) deskRow.get(AppticsConstants.GUESTCONTACTID);
122					String refreshToken = (String) deskRow.get(AppticsConstants.REFRESHTOKEN);
123					Long zuid = (Long) deskRow.get(AppticsConstants.ZUID);
124	//				DeskIntegration.checkAndAddRefreshToken(zuid, refreshToken);
125					Long juID = UserHandler.getAnalyticsUserID(zuid);
126					
127					configuration.put("orgid", orgID);
128					configuration.put("departmentid", departmentID);
129					configuration.put("orgname", orgName);
130					configuration.put("departmentname", departmentname);
131					configuration.put("guestcontactid", guestContactID);
132					configuration.put("zuid", zuid);
133		
134					Iterator<Row> moduleRows = dobj.getRows(AppticsConstants.MODULEINTEGRATION);
135		
136					JSONObject subtype = new JSONObject();
137					subtype.put("feedback", false);
138					subtype.put("bug", false);
139					subtype.put("help", false);
140					subtype.put("report", false);
141					while (moduleRows.hasNext())
142					{
143						Row moduleRow = moduleRows.next();
144						String modulename = modules.get(moduleRow.get(AppticsConstants.MODULEID));
145						if(subtype.has(modulename))
146						{
147							subtype.put(modulename, true);
148						}
149					}
150					configuration.put("subtype", subtype);
151					
152					JSONObject overallconf = new JSONObject();
153					overallconf.put("feedback", configuration);
154					
155					Long modeID = ModeHandler.getModeID(1);
156					
157					List<Long> apIDs = AppHandler.getInstance().getAPIDs(projectID, modeID);
158					
159					if(CommonUtil.isEmpty(apIDs) || apIDs.isEmpty())
160					{
161						LOGGER.info("There are no production AppPlatform.");
162						return;
163					}
164					
165					for (Long apID : apIDs)
166					{
167						JSONObject existConfiguration = IntegrationHandler.getConfiguration(AppticsConstants.NEWDESKINTEGRATION, apID);
168						
169						if(CommonUtil.isEmpty(existConfiguration))
170						{
171							Row r = new Row(AppticsConstants.NEWDESKINTEGRATION);
172							r.set(AppticsConstants.APID, apID);
173							r.set(AppticsConstants.CONFIGURATION, overallconf);
174							r.set(AppticsConstants.JUID, juID);
175							r.set(AppticsConstants.DATE, CalendarUtil.currentTimeMillis());
176							
177							LOGGER.log(Level.INFO, r.toString());
178							
179							DBHandler.insertRow(r, AppticsConstants.NEWDESKINTEGRATION, AppticsConstants.APID);
180						}
181						else
182						{
183							IntegrationHandler.updateConfiguration(AppticsConstants.NEWDESKINTEGRATION, apID, overallconf);
184						}
185					}
186				}
187			}
188			catch(Exception e)
189			{
190				LOGGER.log(Level.SEVERE, "Exception while migrate desk integration", e);
191			}
192		}
193			
194		private static void setModules(Map<Long, String> modules) throws DataAccessException
195		{
196			try
197			{
198				Criteria c = new Criteria(Column.getColumn(AppticsConstants.APPLICATIONLOGTYPE, AppticsConstants.STATUS), true, QueryConstants.EQUAL);
199				List<Map<String, Object>> columnsValues = DBHandler.getColumnsValues(AppticsConstants.APPLICATIONLOGTYPE, c);
200				
201				if(CommonUtil.isEmpty(columnsValues))
202				{
203					LOGGER.log(Level.INFO, "Application log types are not there.");
204					return;
205				}
206				
207				for (int i = 0; i < columnsValues.size(); i++)
208				{
209					Map<String, Object> module = columnsValues.get(i);
210					
211					Long typeID = (Long) module.get(AppticsConstants.TYPEID);
212					String type = (String) module.get(AppticsConstants.C_TYPE);
213					
214					modules.put(typeID, type.toLowerCase());
215				}
216			}
217			catch(Exception e)
218			{
219				LOGGER.log(Level.SEVERE, "Exception in get module ids", e);
220			}
221		}
222		
223		
224	}
