318			int number = 0;
319			if(classification.equalsIgnoreCase("")){
320				number = 0;
321			}
322			else if(classification.equalsIgnoreCase("Question")){
323				number = 1;
324			}
325			else if(classification.equalsIgnoreCase("Problem")){
326				number = 2;
327			}
328			else if(classification.equalsIgnoreCase("Feature")){
329				number = 3;
330			}
331			else if(classification.equalsIgnoreCase("Others")){
332				number = 4;
333			}
334			return number;
335		}
