371		public static boolean updateAppTicket(long appID)
372		{
373			try
374			{
375				String selectQuery = "select IntegrationDetails from BugReportDetails AppID=?;";
376				JSONArray tickets = JDBUtil.getJanalBean().getResultAsJSONArray(selectQuery, appID);
377				
378				for(int i=0; i<tickets.length(); i++)
379				{
380					JSONObject ticket = tickets.getJSONObject(i);
381					JSONObject desk = ticket.getJSONObject("Desk");
382					Long orgID = desk.getLong("OrgID");
