27	    public Pair<String, String> getDeskDataFromIntegrationDetails(String prefix, String integrationDetails) {
28	        if (integrationDetails != null) {
29	            try {
30	                return getDeskDataPairFromJson(integrationDetails);
31	            } catch (JSONException e) {
32	                LOGGER.severe(prefix + " - JSONException in updateDeskTicketIdForStoreReviews: " + e);
33	                if (e.toString().contains("Unterminated string")) {
34	                    return getDeskDataPairFromJson(integrationDetails + "\"}}");
35	                }
36	            }
37	        }
38	        return null;
39	    }
