45	    public Pair<String, String> getDeskDataPairFromJson(JSONObject integrationJson) throws JSONException {
46	        if (integrationJson != null && integrationJson.has(DESK)) {
47	            JSONObject deskJson = filterDeskJsonFields(integrationJson.getJSONObject(DESK));
48	            String deskTicketId = deskJson.getString("id");
49	            return Pair.of(deskTicketId, integrationJson.toString());
50	        }
51	        return null;
52	    }
