54	    public static JSONObject filterDeskJsonFields(JSONObject deskJson) {
55	        Iterator<String> deskJsonKeyIterator = deskJson.keys();
56	        while (deskJsonKeyIterator.hasNext()) {
57	            String key = deskJsonKeyIterator.next();
58	            if (!DESK_REQ_KEYS.contains(key)) {
59	                deskJsonKeyIterator.remove();
60	            }
61	        }
62	        return deskJson;
63	    }
