81	    private JSONObject updateASRDeskTicket(AppStoreReview review, JSONObject oldData, JSONObject deskTicketJson) {
82	        Long reviewLastModified = review.getReviewerComment().getCreatedDate();
83	        if (deskTicketJson.has(DESK_ID)) {
84	            if (isDeskUpdatePending(deskTicketJson, reviewLastModified)) {
85	                String ticketId = deskTicketJson.getString(DESK_ID);
86	
87	                JSONObject deskComment = createCommentForASRDeskTicket(ticketId, review, oldData);
88	                LOGGER.info("deskCommentForPlayStoreReview: " + deskComment);
89	
90	                if (deskComment != null && deskComment.has(DESK_ID)) {
91	                    String commentId = deskComment.getString(DESK_ID);
92	                    JSONArray commentsArray = deskTicketJson.has(DESK_COMMENTS) ? deskTicketJson.getJSONArray(DESK_COMMENTS) : new JSONArray();
93	                    ArrayList<String> comments = StoreUtils.convertToArrayList(commentsArray);
94	                    if (!comments.contains(commentId)) {
95	                        comments.add(commentId);
96	                        deskTicketJson.put(DESK_COMMENTS, StoreUtils.convertToJsonArray(comments));
97	                    }
98	                    JSONObject ticketStatus = updateForASRDeskTicketStatus(ticketId, DESK_STATUS_OPEN);
99	                    LOGGER.info("commentsArray: " + commentsArray + "\n\nUpdated deskTicketJson: " + deskTicketJson + "\n\nUpdated ticketStatus: " + ticketStatus);
100	                }
101	            }
102	            deskTicketJson.put(APPTICS_REVIEW_LAST_MODIFIED, reviewLastModified);
103	        } else {
104	            LOGGER.severe("updateASRDeskTicket :: Ticket ID not found - " + deskTicketJson);
105	        }
106	        return deskTicketJson;
107	    }
