275	    private boolean isDeskSubTypeEnabled(String reviewType) {
276	        if (deskDetails == null || !deskDetails.has(MODULE_SUBTYPE)) {
277	            return false;
278	        }
279	        JSONObject deskSubType = deskDetails.getJSONObject(MODULE_SUBTYPE);
280	        if (NEW_REVIEW.equals(reviewType)) {
281	            return deskSubType.has(DESK_SUBTYPE_NEW) && deskSubType.getBoolean(DESK_SUBTYPE_NEW);
282	        } else if (UPDATED_REVIEW.equals(reviewType)) {
283	            return deskSubType.has(DESK_SUBTYPE_UPDATES) && deskSubType.getBoolean(DESK_SUBTYPE_UPDATES);
284	        } else if (REVIEW_TYPE_UNKNOWN.equals(reviewType)) {
285	            return true;
286	        }
287	        return false;
288	    }
